-- Catalogo Norvegia, versione 2 (NO-2).
-- GENERATO da scripts/seed-catalog.ts: non modificare a mano, rigenerare con `npx tsx scripts/seed-catalog.ts --country NO --version 2`.
-- Prerequisito: migrazioni supabase/migrations/20261106000100 … 20261106000500 e 20261109000000_traghetti.sql.
-- Contiene tutta la versione NO-1 (controllo finale: righe identiche per chiave) e la indica come versione precedente.
-- Idempotente: con la versione già pubblicata non scrive nulla e controlla solo i conteggi.
-- Tocca solo le tabelle del catalogo: nessun viaggio, nessun dato di auth.

begin;

-- Prerequisiti: versione precedente pubblicata, tabelle dei traghetti presenti
do $pre$
begin
  if not exists (select 1 from public.catalog_releases where release_id = 'NO-1' and status in ('pubblicata', 'ritirata')) then
    raise exception 'La versione precedente NO-1 non è pubblicata: applicare prima il suo seed';
  end if;
  if to_regclass('public.ferry_routes') is null then
    raise exception 'Mancano le tabelle dei traghetti: applicare prima supabase/migrations/20261109000000_traghetti.sql';
  end if;
end $pre$;

on conflict (code) do nothing;

on conflict (release_id) do nothing;

on conflict (place_key) do nothing;

on conflict (iata) do nothing;

-- Contenuto della versione: si scrive solo se è ancora in bozza
do $seed$
begin
  if not exists (select 1 from public.catalog_releases where release_id = 'NO-2' and status = 'bozza') then
    raise notice 'Versione NO-2 già pubblicata: nessuna scrittura, solo controllo';
    return;
  end if;













end $seed$;

update public.catalog_releases set status = 'pubblicata', published_at = now() where release_id = 'NO-2' and status = 'bozza';

-- Controllo finale: se fallisce, la transazione si annulla
do $check$
declare
  v_n bigint;
begin
  if not exists (select 1 from public.countries where code = 'NO' and currency = 'NOK' and timezone = 'Europe/Oslo' and language = 'nb') then
    raise exception 'Nazione NO: valuta, fuso o lingua diversi da quelli del seed';
  end if;
  perform now() at time zone 'Europe/Oslo';
  if not exists (select 1 from public.catalog_releases where release_id = 'NO-2' and status = 'pubblicata') then
    raise exception 'Versione NO-2 non pubblicata';
  end if;
  select count(*) into v_n from public.regions where release_id = 'NO-2';
  if v_n <> 7 then raise exception 'regions (release_id = ''NO-2''): attese 7 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-2';
  if v_n <> 117 then raise exception 'places (release_id = ''NO-2''): attese 117 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_texts where release_id = 'NO-2';
  if v_n <> 117 then raise exception 'place_texts (release_id = ''NO-2''): attese 117 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_sources where release_id = 'NO-2';
  if v_n <> 394 then raise exception 'place_sources (release_id = ''NO-2''): attese 394 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.operators where release_id = 'NO-2';
  if v_n <> 2 then raise exception 'operators (release_id = ''NO-2''): attese 2 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.voyages where release_id = 'NO-2';
  if v_n <> 24 then raise exception 'voyages (release_id = ''NO-2''): attese 24 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.route_ports where release_id = 'NO-2';
  if v_n <> 35 then raise exception 'route_ports (release_id = ''NO-2''): attese 35 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_links where release_id = 'NO-2';
  if v_n <> 9 then raise exception 'place_links (release_id = ''NO-2''): attese 9 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-2' and category = 'porti';
  if v_n <> 35 then raise exception 'places (release_id = ''NO-2'' and category = ''porti''): attese 35 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-2' and coords_status = 'verificate';
  if v_n <> 72 then raise exception 'places (release_id = ''NO-2'' and coords_status = ''verificate''): attese 72 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-2' and official_url is not null;
  if v_n <> 29 then raise exception 'places (release_id = ''NO-2'' and official_url is not null): attese 29 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-2' and wikidata_qid is not null;
  if v_n <> 77 then raise exception 'places (release_id = ''NO-2'' and wikidata_qid is not null): attese 77 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-2' and base_place_key is not null;
  if v_n <> 8 then raise exception 'places (release_id = ''NO-2'' and base_place_key is not null): attese 8 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_sources where release_id = 'NO-2';
  if v_n <> 36 then raise exception 'ferry_sources (release_id = ''NO-2''): attese 36 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_routes where release_id = 'NO-2';
  if v_n <> 58 then raise exception 'ferry_routes (release_id = ''NO-2''): attese 58 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_route_stops where release_id = 'NO-2';
  if v_n <> 207 then raise exception 'ferry_route_stops (release_id = ''NO-2''): attese 207 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_route_places where release_id = 'NO-2';
  if v_n <> 58 then raise exception 'ferry_route_places (release_id = ''NO-2''): attese 58 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_fares where release_id = 'NO-2';
  if v_n <> 91 then raise exception 'ferry_fares (release_id = ''NO-2''): attese 91 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_route_stops where release_id = 'NO-2' and lat is not null;
  if v_n <> 200 then raise exception 'ferry_route_stops (release_id = ''NO-2'' and lat is not null): attese 200 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.ferry_fares where release_id = 'NO-2' and amount is not null;
  if v_n <> 84 then raise exception 'ferry_fares (release_id = ''NO-2'' and amount is not null): attese 84 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.catalog_releases where release_id = 'NO-2' and previous_release_id = 'NO-1';
  if v_n <> 1 then raise exception 'catalog_releases (release_id = ''NO-2'' and previous_release_id = ''NO-1''): attese 1 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places p join public.place_keys k on k.place_key = p.place_key where p.release_id = 'NO-2' and k.country_code <> 'NO';
  if v_n <> 0 then raise exception 'Chiavi di luogo registrate per un''altra nazione: %', v_n; end if;
  select count(*) into v_n from public.places p where p.release_id = 'NO-2' and not exists (select 1 from public.place_texts t where t.release_id = p.release_id and t.place_key = p.place_key and t.lang = 'it');
  if v_n <> 0 then raise exception 'Luoghi senza testo italiano: %', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.regions x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.regions x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'regions: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.places x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.places x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'places: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_texts x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.place_texts x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'place_texts: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_sources x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.place_sources x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'place_sources: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.operators x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.operators x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'operators: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.voyages x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.voyages x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'voyages: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.route_ports x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.route_ports x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'route_ports: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_links x where x.release_id = 'NO-1'
    except select to_jsonb(x) - 'release_id' from public.place_links x where x.release_id = 'NO-2') d;
  if v_n <> 0 then raise exception 'place_links: % righe di NO-1 mancano o sono diverse in NO-2 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from public.ferry_routes r where r.release_id = 'NO-2' and not exists (select 1 from public.ferry_route_stops s where s.release_id = r.release_id and s.route_key = r.route_key);
  if v_n <> 0 then raise exception 'Tratte senza tappe: %', v_n; end if;
  raise notice 'Catalogo NO-2 pubblicato e controllato: 117 luoghi, 24 crociere, 35 porti in rotta, 58 tratte traghetto';
end $check$;

commit;
